const url = new URL("https://app.selltostate.com/api/v1/awards");
url.search = new URLSearchParams({ q: "cybersecurity", page_size: "5" });

const resp = await fetch(url, {
  headers: { "x-api-key": "sts_xxxxxxxx" },
});
if (resp.status === 402) throw new Error("subscription required");
const data = await resp.json();
console.log(`${data.total} awards; ${data.rows.length} on this page`);

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

func main() {
	req, _ := http.NewRequest("GET", "https://app.selltostate.com/api/v1/awards?q=cybersecurity&page_size=5", nil)
	req.Header.Set("x-api-key", "sts_xxxxxxxx")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusPaymentRequired {
		panic("subscription required (402)")
	}

	var out struct {
		Total int `json:"total"`
		Rows  []map[string]any `json:"rows"`
	}
	json.NewDecoder(resp.Body).Decode(&out)
	fmt.Printf("%d awards; %d on this page\n", out.Total, len(out.Rows))
}

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

func main() {
	resp, err := http.Get("https://app.selltostate.com/api/v1/price")
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()

	var price struct {
		Formatted string `json:"formatted"`
		Currency  string `json:"currency"`
	}
	json.NewDecoder(resp.Body).Decode(&price)
	fmt.Printf("%s (%s)\n", price.Formatted, price.Currency)
}
